# The job dir name for this run, as an Airflow template expression. Every task
# except the init one cd's into WORK_ROOT/<this>.
DIR_NAME = "{{ var.json[run_id].dir_name }}"

# The whole run-id Variable payload (the JSON blob SARFinder wrote).
RUN_PAYLOAD = "{{ var.value[run_id] }}"

INIT_STEP = "00a_prepare_directory"

# What a live_payload task finds the run payload in (orch.core.fpm2.PAYLOAD_ENV).
PAYLOAD_ENV = "ORCH_RUN_PAYLOAD"

# Its return value (XCom) is the run payload as triggered — the continuity
# listener's baseline.
SET_VARIABLES_TASK_ID = "set_variables"

# `orch run` exits this when every task in the slice was gated out by `when:`.
# Under Airflow every task is a one-task slice, so it means exactly "this task
# was gated out". Kept in sync with orch.core.runner.EXIT_ALL_SKIPPED.
SKIP_EXIT_CODE = 99

# Echoed to stderr by the remote wrapper when orch reports the skip. See
# _skip_wrapper for why the literal must never appear in the command itself.
SKIP_MARKER = "ORCH_SKIPPED_99"

# A step exits this to say "not yet, call me again" (ALOS stack_init/02_fetch_data
# while a JAXA delivery is pending); `orch run` passes it on. Kept in sync with
# orch.core.runner.EXIT_WAITING. OrchSSHOperator turns it into
# AirflowRescheduleException, so the task waits up_for_reschedule without holding
# a worker slot, like the continuity sensors. The deadline lives in the step
# (job dir), not here, so a manual `orch run` behaves the same.
WAITING_EXIT_CODE = 98
WAITING_MARKER = "ORCH_WAITING_98"
DEFAULT_RESCHEDULE_SECONDS = 1800

# Every generated task and the whole tail run on this rule: all upstreams
# terminal, none FAILED or UPSTREAM_FAILED — a SKIPPED upstream counts as OK.
# That is a bit-exact reproduction of the pre-skip behaviour, where a gated-out
# task exited 0 and satisfied `all_success`.
#
# The tail matters most: emit.py wires EVERY leaf into slack -> job status ->
# cleanup, so under `all_success` a single skipped branch would suppress the
# SARFinder status POST and leave the job stuck in "running" forever.
#
# Not `none_failed_min_one_success` — it would break the degenerate run where
# every branch skipped, which today is all-green and does reach the tail.
# Not `all_done` — it fires on upstream FAILURE too, so a failed run would post
# "products are ready" and then POST success, overwriting the failure the
# on_failure_callback had already reported.
# Not `none_failed_or_skipped` — deprecated in Airflow 2.2, removed in 2.5.
DEFAULT_TRIGGER_RULE = "none_failed"


# ── command construction ─────────────────────────────────────────────────────


def ssh_cmd(script: str, *, setup_cmd: str, work_root: str, use_dir: bool = True) -> str:
    """Build the remote command: source the env, optionally cd into the job dir.

    ``use_dir=False`` is for the init step, which runs before the job dir (and
    its config.txt) exists.
    """
    base = setup_cmd
    if use_dir:
        base += f"; cd {work_root}/{DIR_NAME}"
    return f"{base}; {script}"


def _skip_wrapper(script: str) -> str:
    """Wrap a command so an all-skipped `orch run` is detectable over SSH.

    POSIX sh only — the remote login shell is not guaranteed to be bash.

    The marker is assembled with ``printf`` from three separate arguments
    instead of being echoed as a literal, and that is LOAD-BEARING. Older ssh
    providers raise ``AirflowException(f"error running cmd: {self.command}, "
    f"error: {stderr}")`` — the command text itself lands in the message. If
    the contiguous literal appeared in the command, ``is_skip_error`` would
    match on EVERY genuine failure and silently turn it into a skip. Assembling
    it at runtime means the string exists only in real stderr. Do not
    "simplify" this line.
    """
    return (
        f"{script}; rc=$?; "
        f'if [ "$rc" -eq {SKIP_EXIT_CODE} ]; then '
        f"printf '%s_%s_%s\\n' ORCH SKIPPED {SKIP_EXIT_CODE} >&2; fi; "
        f'if [ "$rc" -eq {WAITING_EXIT_CODE} ]; then '
        f"printf '%s_%s_%s\\n' ORCH WAITING {WAITING_EXIT_CODE} >&2; fi; "
        'exit "$rc"'
    )


_SKIP_PATTERNS = (SKIP_MARKER, f"exit status = {SKIP_EXIT_CODE}")


def is_skip_error(message: str) -> bool:
    """True when an SSHOperator failure is really an orch "gated out" signal.

    Two patterns because the host's ssh-provider generation is unknown: newer
    ones put ``exit status = 99`` in the exception message, older ones carry
    the command's stderr (and so the marker). Module-level and pure so the test
    suite can exercise it without Airflow installed.
    """
    return any(p in message for p in _SKIP_PATTERNS)


_WAITING_PATTERNS = (WAITING_MARKER, f"exit status = {WAITING_EXIT_CODE}")


def is_waiting_error(message: str) -> bool:
    """True when an SSHOperator failure is really an orch "waiting, call again" signal.

    Same two provider generations as :func:`is_skip_error`, and the same guard:
    the marker is assembled at runtime by ``_skip_wrapper``, so a genuine failure
    that echoes the command back can never match.
    """
    return any(p in message for p in _WAITING_PATTERNS)


class OrchSSHOperator(SSHOperator):
    """SSHOperator that renders a `when:`-gated orch task as SKIPPED, not failed.

    Gates are evaluated inside ``orch run`` on the remote head node — against
    the live config.txt and filesystem — so the decision cannot be made here or
    at DAG-parse time. This turns the remote signal into Airflow's own state.

    Failure mode if the provider surfaces neither pattern: the task goes red
    rather than pink. Loud and safe — the reverse direction (a real failure
    silently becoming a skip) is the one that must never happen, and it is
    guarded by ``_skip_wrapper``'s runtime-assembled marker.
    """

    def __init__(self, *args, reschedule_seconds: int = DEFAULT_RESCHEDULE_SECONDS, **kwargs):
        super().__init__(*args, **kwargs)
        # How long a task whose step exited WAITING_EXIT_CODE waits before
        # Airflow runs it again (dags.yaml task_overrides: reschedule_seconds).
        self.reschedule_seconds = int(reschedule_seconds)

    def execute(self, context):
        try:
            return super().execute(context)
        except (AirflowSkipException, AirflowRescheduleException):
            # Provider-native skip_on_exit_code already decided. Must be caught
            # first: both subclass AirflowException.
            raise
        except AirflowException as e:
            if is_skip_error(str(e)):
                raise AirflowSkipException(
                    f"orch: {self.task_id} gated out by its `when:` condition"
                ) from None
            if is_waiting_error(str(e)):
                # up_for_reschedule: no worker slot held while waiting, and the
                # step's own deadline turns a wait that never ends into a failure.
                raise AirflowRescheduleException(
                    datetime.now(timezone.utc) + timedelta(seconds=self.reschedule_seconds)
                ) from None
            raise


def orch_task(task_id, orch_name, *, ssh_conn_id, setup_cmd, work_root, live_payload=False, **kwargs):
    """One Airflow task = one orch pipeline task.

    Runs ``orch run <name> <name>`` rather than ``orch run-step``: the ``run``
    path substitutes ``${key}`` argv against config.txt, evaluates the task's
    ``when:`` gates, records the manifest entry, and tees output to
    ``log/orch/<name>.log``. ``run-step`` does none of that.

    A gated-out task exits ``SKIP_EXIT_CODE`` and renders as Airflow SKIPPED
    (see OrchSSHOperator). ``trigger_rule="none_failed"`` then keeps that skip
    from cascading: every downstream task still runs and evaluates its OWN
    gate, exactly as a local ``orch run`` does. With the default
    ``all_success``, Airflow would prune whole branches without ever consulting
    their gates — which would silently drop real work, e.g. the ungated
    ``dpm3/upload_greyscale`` on a job that simply didn't select dpm3.

    ``orch_name`` is the orch task id and may contain ``/`` (block namespacing);
    ``task_id`` is the Airflow id within its TaskGroup and may not.

    ``live_payload=True`` (dags.yaml ``task_overrides``) also exports the run's
    current run-id Variable as ``ORCH_RUN_PAYLOAD``, through the same
    ``export ... | tr -d '\\n'`` hop the init task uses. config.txt is written
    once, by 00a, so this is how a task re-run from the UI ("Re-run from here")
    sees settings edited in the Variable since: the step merges the keys it
    owns into config.txt before running (fpm2/zscore and fpm2/gsba; see
    orch/core/fpm2.py). Only for tasks that read it: a single quote in the
    payload breaks the hop, which SARimpact refuses for that reason.
    """
    kwargs.setdefault("cmd_timeout", None)
    kwargs.setdefault("conn_timeout", None)
    kwargs.setdefault("trigger_rule", DEFAULT_TRIGGER_RULE)
    # Native support is exact where it exists; the OrchSSHOperator fallback
    # covers the providers that lack it. Probing beats a version check.
    try:  # pragma: no cover - depends on the host's provider version
        if "skip_on_exit_code" in inspect.signature(SSHOperator.__init__).parameters:
            kwargs.setdefault("skip_on_exit_code", SKIP_EXIT_CODE)
    except (TypeError, ValueError):
        pass
    script = _skip_wrapper(f"orch run '{orch_name}' '{orch_name}' --job-dir .")
    if live_payload:
        script = f"export {PAYLOAD_ENV}=$(echo '{RUN_PAYLOAD}' | tr -d '\\n') && {script}"
    return OrchSSHOperator(
        task_id=task_id,
        ssh_conn_id=ssh_conn_id,
        command=ssh_cmd(script, setup_cmd=setup_cmd, work_root=work_root),
        **kwargs,
    )


def orch_init_task(task_id, *, pipeline, ssh_conn_id, setup_cmd, work_root, **kwargs):
    """The init task — the one exception to the ``orch run`` rule.

    ``00a_prepare_directory`` creates the job dir, so it cannot cd into it, and
    there is no config.txt yet to substitute against. It takes the run payload
    as ``--json``; the ``export VARIABLE=$(... | tr -d '\\n')`` hop (inherited
    from the hand-written DAGs) gets the JSON blob past two layers of shell
    quoting. ``--root`` is absolute so 00a's nesting guard can never trip.
    """
    kwargs.setdefault("cmd_timeout", None)
    kwargs.setdefault("conn_timeout", None)
    body = (
        f"export VARIABLE=$(echo '{RUN_PAYLOAD}' | tr -d '\\n') && "
        f"orch run-step {INIT_STEP} -- "
        f"--root {work_root} --pipeline {pipeline} --json \"$VARIABLE\""
    )
    return SSHOperator(
        task_id=task_id,
        ssh_conn_id=ssh_conn_id,
        command=ssh_cmd(body, setup_cmd=setup_cmd, work_root=work_root, use_dir=False),
        **kwargs,
    )


# ── failure handling ─────────────────────────────────────────────────────────


def make_failure_callback(*, slack_conn_id, slack_channel, http_conn_id, http_endpoint):
    """Build the on-failure callback: Slack alert, then mark the job failed.

    A factory rather than a module-level function because the Slack connection
    and channel now vary per DAG.
    """

    def failure_callback(context):
        dag_run = context.get("dag_run")
        dag_run_id = dag_run.run_id if dag_run else "unknown"
        ti = context.get("task_instance")

        try:
            slack_msg = f"""
            :red_circle: Task Failed. Please go to Airflow for more details.
            *Task*: {ti.task_id if ti else "unknown"}
            *Dag*: {ti.dag_id if ti else "unknown"}
            *Execution Time*: {context.get("execution_date")}
            *Log Url*: {ti.log_url if ti else "unknown"}
        """
            SlackWebhookOperator(
                task_id="slack_failed_alert",
                slack_webhook_conn_id=slack_conn_id,
                message=slack_msg,
                username="airflow",
                channel=slack_channel,
            ).execute(context=context)
        except Exception as slack_error:  # noqa: BLE001 - never mask the real failure
            print(f"Failed to send Slack alert: {slack_error}")

        try:
            SimpleHttpOperator(
                task_id="update_job_status",
                http_conn_id=http_conn_id,
                endpoint=http_endpoint,
                method="POST",
                headers={"Content-Type": "application/json"},
                data=json.dumps({"status": "failed", "dag_run_id": "{{ run_id }}"}),
            ).execute(context=context)
            print(f"Updated status to failed for DAG run {dag_run_id}")
        except requests.RequestException as http_error:
            print(f"Failed to update job status: {http_error}")

    return failure_callback


# ── run payload plumbing ─────────────────────────────────────────────────────


def set_variables_task(dag_id: str):
    """Copy this run's payload into a Variable keyed by ``run_id``.

    When that Variable already exists it is returned unchanged: post-event
    continuity re-runs this same run (see ``continuity_rerun_task``) with the
    user-edited Variable as its payload.

    Prefers ``dag_run.conf`` (what a trigger passes directly) and falls back to
    the legacy ``{DAG_ID}_variables`` Variable. The fallback races when two runs
    of the same DAG are triggered close together — which the old
    satellite x product DAG matrix made unlikely and the collapse to one DAG per
    satellite makes likely. Passing the payload as trigger conf avoids it.
    """

    def set_variables(**kwargs):
        run_id = kwargs["run_id"]
        # A continuity re-run of this same run (rerun_update), or a retry: the
        # Variable is the payload now — it holds the user's edits, which the
        # original trigger conf would overwrite.
        existing = Variable.get(run_id, default_var=None)
        if existing is not None:
            return existing
        dag_run = kwargs.get("dag_run")
        conf = (dag_run.conf or {}) if dag_run else {}
        payload = json.dumps(conf) if conf else Variable.get(f"{dag_id}_variables")
        Variable.set(run_id, payload)
        return payload

    return PythonOperator(
        task_id=SET_VARIABLES_TASK_ID,
        python_callable=set_variables,
        provide_context=True,
    )


def cleanup_variables_task(**kwargs):
    def cleanup_variables(**context):
        Variable.delete(context["run_id"])
        # Left by listen_event_dates after a refused or held edit (post-event continuity).
        Variable.delete(f"{context['run_id']}__refused")
        Variable.delete(f"{context['run_id']}__hold")

    kwargs.setdefault("trigger_rule", DEFAULT_TRIGGER_RULE)
    return PythonOperator(
        task_id="cleanup_variables",
        python_callable=cleanup_variables,
        provide_context=True,
        **kwargs,
    )


# ── tail ─────────────────────────────────────────────────────────────────────


def slack_tail(*, slack_conn_id, slack_channel, message, **kwargs):
    kwargs.setdefault("trigger_rule", DEFAULT_TRIGGER_RULE)
    return SlackWebhookOperator(
        task_id="send_slack_notifications",
        slack_webhook_conn_id=slack_conn_id,
        message=message,
        channel=slack_channel,
        username="airflow",
        **kwargs,
    )


def job_status_task(*, http_conn_id, endpoint, status="success", **kwargs):
    kwargs.setdefault("trigger_rule", DEFAULT_TRIGGER_RULE)
    return SimpleHttpOperator(
        task_id="update_job_status",
        http_conn_id=http_conn_id,
        endpoint=endpoint,
        method="POST",
        headers={"Content-Type": "application/json"},
        data=json.dumps({"status": status, "dag_run_id": "{{ run_id }}"}),
        extra_options={"check_response": False},
        **kwargs,
    )


# ── post-event continuity ────────────────────────────────────────────────────
#
# A job whose payload sets post_event_continuity=true does not end after its
# status POST: listen_event_dates watches this run's own run-id Variable (the
# payload set_variables wrote) for new selection_download scenes, and
# rerun_update re-runs THIS run in place — same run id, same dir_name, same
# Variable. 00a finds the job already built and runs it as a later pass
# (orch.core.update processes only the new dates). Setting
# post_event_continuity=false in the Variable ends the run.
#
# selection_download is the only trigger: every scene on or after the earliest
# event_date is a post-event map, so appending a date's scenes is how a waiting
# job gets its post-event scene and how a running one gets another map. An
# event_date edit alone does not trigger (it is merged by the next pass). All
# frames of a date must arrive in one edit: a new date with fewer scenes than
# the pre-event dates have is held (not triggered) until it is complete or the
# hold expires.
#
# The baseline — what this run actually processed — is set_variables' return
# value (XCom), since the Variable itself is what the user edits.

CONTINUITY_KEY = "post_event_continuity"
LISTEN_TASK_ID = "listen_event_dates"
RERUN_TASK_ID = "rerun_update"
_DATE = re.compile(r"^\d{8}$")
# The acquisition date in an S1 SLC / NISAR RSLC/GSLC name: the first
# _YYYYMMDDTHHMMSS. A test pins it to the satellite readers' scene_date.
_SCENE_DATE = re.compile(r"_(\d{8})T\d{6}")


def _truthy(value) -> bool:
    return str(value).strip().strip("'\"").lower() == "true"


def _refused_variable(run_id: str) -> str:
    """Remembers the last refused edit, so its Slack alert goes out once."""
    return f"{run_id}__refused"


def _hold_variable(run_id: str) -> str:
    """Remembers a held (incomplete) selection: since when, and what was noted."""
    return f"{run_id}__hold"


def event_date_set(value) -> list[str]:
    """Sorted unique YYYYMMDD entries of an event_date (comma string or JSON list).

    Same rules as orch.core.dpm_dates._date_list, which this module cannot
    import (it runs on the Airflow host); a test pins the two together.
    """
    items = value if isinstance(value, list) else str(value or "").split(",")
    dates = sorted({str(d).strip() for d in items if str(d).strip()})
    bad = [d for d in dates if not _DATE.match(d)]
    if bad:
        raise ValueError(f"event_date has non-YYYYMMDD entries: {', '.join(bad)}")
    return dates


def scene_set(value) -> list[str]:
    """Sorted unique scene names of a selection_download (JSON list, or a
    comma/newline-separated string)."""
    items = value if isinstance(value, list) else re.split(r"[,\n]", str(value or ""))
    return sorted({str(s).strip() for s in items if str(s).strip()})


def scene_date(name: str) -> str:
    """YYYYMMDD acquisition date of a scene name, or '' when it has none."""
    m = _SCENE_DATE.search(str(name))
    return m.group(1) if m else ""


def _expected_frames(scenes, first_event: str) -> int:
    """Scenes per date the pre-event dates usually have (the most common count)."""
    counts = Counter(d for d in map(scene_date, scenes) if d and d < first_event)
    if not counts:
        return 1
    tally = Counter(counts.values())
    return max(n for n, k in tally.items() if k == max(tally.values()))


def earliest_change_refusal(job: dict, old: str, new: str, new_modes=None) -> str:
    """Why the earliest event_date may not move from ``old`` to ``new`` ('' = it may).

    With an empty ``pre_event_dates`` the reference set is every date before the
    earliest event_date, so moving it changes the references: refused. With an
    explicit list the references do not depend on it, so the move is allowed when
    the new earliest is after the last reference and no dpm1 map (one map, built
    on the earliest date, not incrementally) would silently change event.
    ``job`` is the job's payload (``pre_event_dates`` is frozen); ``new_modes`` is
    the edited ``modes``, checked for dpm1 too.
    Same rule as orch.core.update.check_frozen; a test pins the two together.
    """
    head = f"new earliest event_date {new} (was {old})"
    try:
        pre = event_date_set(job.get("pre_event_dates"))
    except ValueError as e:
        return f"{head}; pre_event_dates: {e}"
    if not pre:
        return (f"{head}; with no pre_event_dates it defines the pre-event reference "
                f"set, so a full run is needed")
    if new <= pre[-1]:
        return (f"{head} is not after the last pre_event_date {pre[-1]}")
    modes = set()
    for raw in (job.get("modes"), new_modes):
        raw = raw or ""
        modes |= {str(m).strip().lower()
                  for m in (raw if isinstance(raw, list) else str(raw).split(","))}
    if "dpm1" in modes:
        return f"{head}; dpm1's single map is built on the earliest date, so a full run is needed"
    return ""


def continuity_decision(run_payload: dict, watched: dict) -> tuple[str, str]:
    """What the listener does with the edited Variable: ``(decision, reason)``.

    - ``stop``: continuity switched off.
    - ``refused``: an edit a later pass's 00a would reject — a removed scene, a
      new scene dated before the earliest event_date (the references are
      frozen), a new scene on a date this run already has (a date's frames come
      in one edit), a scene name without a date, or an event_date edit that
      drops a date or moves the earliest one where
      :func:`earliest_change_refusal` forbids it.
    - ``hold``: new post-event scenes, but some new date has fewer scenes than
      the pre-event dates have — wait for the rest of its frames.
    - ``trigger``: new post-event scenes, every new date complete.
    - ``wait``: no new scene (an event_date edit alone does not trigger).
    """
    if not _truthy(watched.get(CONTINUITY_KEY)):
        return "stop", f"{CONTINUITY_KEY} is no longer true"
    try:
        old = event_date_set(run_payload.get("event_date"))
        new = event_date_set(watched.get("event_date"))
    except ValueError as e:
        return "refused", str(e)
    removed = sorted(set(old) - set(new))
    if removed:
        return "refused", f"event_date dropped {', '.join(removed)}; dates can only be added"
    if old and new and new[0] != old[0]:
        why = earliest_change_refusal(run_payload, old[0], new[0], watched.get("modes"))
        if why:
            return "refused", why
    old_scenes = scene_set(run_payload.get("selection_download"))
    new_scenes = scene_set(watched.get("selection_download"))
    dropped = sorted(set(old_scenes) - set(new_scenes))
    if dropped:
        return "refused", (f"selection_download dropped {', '.join(dropped)}; scenes can "
                           f"only be added")
    added = sorted(set(new_scenes) - set(old_scenes))
    if not added:
        return "wait", ""
    undated = [s for s in added if not scene_date(s)]
    if undated:
        return "refused", f"no _YYYYMMDDThhmmss date in scene name(s) {', '.join(undated)}"
    if not new:
        return "refused", "no event_date: cannot tell post-event scenes from pre-event ones"
    first = new[0]
    early = sorted(s for s in added if scene_date(s) < first)
    if early:
        return "refused", (f"{', '.join(early)} dated before event_date {first}; the "
                           f"pre-event scenes are frozen, only post-event scenes can be added")
    have = {scene_date(s) for s in old_scenes}
    late = sorted({scene_date(s) for s in added} & have)
    if late:
        return "refused", (f"new frame(s) for {', '.join(late)}, a date this job already "
                           f"processed; all frames of a date must be added in one edit")
    expected = _expected_frames(old_scenes, first)
    counts = Counter(scene_date(s) for s in added)
    dates = ", ".join(f"{d} ({n} scene{'s' if n > 1 else ''})" for d, n in sorted(counts.items()))
    short = [f"{d} has {n} of {expected}" for d, n in sorted(counts.items()) if n < expected]
    if short:
        return "hold", (f"new post-event scenes on {dates}, but {'; '.join(short)} scenes the "
                        f"pre-event dates have; waiting for the rest of the frames")
    return "trigger", f"new post-event scene(s) on {dates}"


def _baseline(context) -> dict:
    """The payload this run started with, as set_variables returned it."""
    raw = context["ti"].xcom_pull(task_ids=SET_VARIABLES_TASK_ID)
    if raw is None:
        raise AirflowException("no set_variables XCom: cannot tell which event_date "
                               "this run processed")
    return json.loads(raw) if isinstance(raw, str) else raw


def _notify(context, *, slack_conn_id, slack_channel, message) -> None:
    try:
        SlackWebhookOperator(
            task_id="continuity_alert",
            slack_webhook_conn_id=slack_conn_id,
            message=message,
            username="airflow",
            channel=slack_channel,
        ).execute(context=context)
    except Exception as slack_error:  # noqa: BLE001 - a Slack outage must not stop listening
        print(f"Failed to send Slack alert: {slack_error}")


def continuity_listen_task(dag_id: str, *, slack_conn_id, slack_channel,
                           poke_interval: int, timeout: int, frame_hold: int = 72 * 3600,
                           **kwargs):
    """Wait for new selection_download scenes in this run's run-id Variable.

    Skipped at once unless the payload this run started with has
    post_event_continuity=true. Each poke compares the (user-edited) run-id
    Variable against that baseline (:func:`continuity_decision`); the decision
    and its reason go to XCom (keys ``decision``, ``reason``) for rerun_update.

    A ``hold`` (a new date still missing frames) posts one Slack note per
    selection and keeps waiting; ``frame_hold`` seconds after the first hold it
    triggers anyway, with a warning, so a date that will never be complete does
    not block the job. Reschedule mode, so a job listening for weeks holds no
    worker slot; on ``timeout`` the task soft-fails to SKIPPED and the run ends
    normally.
    """

    def listen(**context):
        run_id = context["run_id"]
        baseline = _baseline(context)
        if not _truthy(baseline.get(CONTINUITY_KEY)):
            raise AirflowSkipException(f"{CONTINUITY_KEY} is not set for this job")
        if not scene_set(baseline.get("selection_download")):
            raise AirflowException(f"{CONTINUITY_KEY} needs selection_download: post-event "
                                   f"scenes are added to it to resume the job")
        watched = json.loads(Variable.get(run_id))
        decision, reason = continuity_decision(baseline, watched)
        print(f"Variable {run_id}: {decision} {reason}".rstrip())
        alert = lambda message: _notify(context, slack_conn_id=slack_conn_id,
                                        slack_channel=slack_channel, message=message)
        where = f"{dag_id} {baseline['dir_name']}"
        if decision == "refused":
            # Once per offending edit, not once per poke.
            seen = _refused_variable(run_id)
            stamp = json.dumps([watched.get("event_date"), watched.get("selection_download")])
            if Variable.get(seen, default_var=None) != stamp:
                Variable.set(seen, stamp)
                alert(f":warning: {where}: update not triggered — {reason}. Fix the "
                      f"Variable {run_id}.")
            return False
        if decision == "hold":
            key = _hold_variable(run_id)
            raw = Variable.get(key, default_var=None)
            held = json.loads(raw) if raw else {}
            since = held.get("since", time.time())
            stamp = scene_set(watched.get("selection_download"))
            if held.get("scenes") != stamp:
                Variable.set(key, json.dumps({"since": since, "scenes": stamp}))
                alert(f":hourglass: {where}: {reason}. Add them to the Variable {run_id}; "
                      f"the update runs without them after {frame_hold // 3600} h.")
            if time.time() - since < frame_hold:
                return False
            alert(f":warning: {where}: frame hold expired; updating with the scenes there "
                  f"are — {reason}")
            decision = "trigger"
        if decision in ("stop", "trigger"):
            Variable.delete(_hold_variable(run_id))
            context["ti"].xcom_push(key="decision", value=decision)
            context["ti"].xcom_push(key="reason", value=reason)
            return True
        return False

    kwargs.setdefault("trigger_rule", DEFAULT_TRIGGER_RULE)
    return PythonSensor(
        task_id=LISTEN_TASK_ID,
        python_callable=listen,
        mode="reschedule",
        poke_interval=poke_interval,
        timeout=timeout,
        soft_fail=True,
        **kwargs,
    )


def _reset_other_tasks(context) -> list[str]:
    """Reset every task instance of this run except the calling one.

    They are all finished when rerun_update gets here (it is the next-to-last
    task and its upstream chain is complete), so nothing running is touched.
    ``dag_run_state=False`` keeps the DagRun RUNNING rather than re-queuing it
    (Airflow >= 2.7). Returns the reset task ids.
    """
    from airflow.models.taskinstance import clear_task_instances
    from airflow.utils.session import create_session

    me = context["ti"].task_id
    with create_session() as session:
        tis = [ti for ti in context["dag_run"].get_task_instances(session=session)
               if ti.task_id != me]
        clear_task_instances(tis, session, dag=context["dag"], dag_run_state=False)
        return [ti.task_id for ti in tis]


def continuity_rerun_task(dag_id: str, *, slack_conn_id, slack_channel, timeout: int,
                          poke_interval: int = 60, **kwargs):
    """Re-run this same run for the update the listener asked for.

    On ``trigger``: reset every other task of the run (00a then sees the job's
    baseline and runs the next pass; a dir_name edit is pinned back to the one
    this run started with), and stay UP_FOR_RESCHEDULE rather than
    succeed. Its upstream is now unstarted, so it cannot poke again until the
    next pass's listener finishes; and cleanup_variables, downstream of a task
    that never finished, keeps the Variable. On ``stop`` or no decision (the
    listener skipped or timed out) it succeeds and cleanup ends the run.

    Reschedule mode, so the wait holds no worker slot. Its ``timeout`` counts
    from its first poke across every pass — the job's whole continuity
    lifetime; on expiry it soft-fails to SKIPPED and cleanup runs.
    """

    def rerun(**context):
        ti = context["ti"]
        decision = ti.xcom_pull(task_ids=LISTEN_TASK_ID, key="decision")
        if decision != "trigger":
            print(f"no update requested (listener decision: {decision}); ending the run")
            return True
        run_id = context["run_id"]
        baseline = _baseline(context)
        payload = json.loads(Variable.get(run_id))
        if payload.get("dir_name") != baseline["dir_name"]:
            payload["dir_name"] = baseline["dir_name"]
            Variable.set(run_id, json.dumps(payload))
        reason = ti.xcom_pull(task_ids=LISTEN_TASK_ID, key="reason") or "new scenes"
        reset = _reset_other_tasks(context)
        message = (f":repeat: {dag_id} {baseline['dir_name']}: re-running {run_id} as the "
                   f"job's next pass for {reason} ({len(reset)} tasks reset)")
        print(message)
        _notify(context, slack_conn_id=slack_conn_id, slack_channel=slack_channel,
                message=message)
        return False

    kwargs.setdefault("trigger_rule", DEFAULT_TRIGGER_RULE)
    return PythonSensor(
        task_id=RERUN_TASK_ID,
        python_callable=rerun,
        mode="reschedule",
        poke_interval=poke_interval,
        timeout=timeout,
        soft_fail=True,
        **kwargs,
    )


# ── customization escape hatch ───────────────────────────────────────────────


def apply_customizations(dag, tasks: dict, *, dag_id: str) -> None:
    """Hand control to ``customize_<DAG_ID>.py`` if the operator wrote one.

    That module defines ``customize(dag, tasks)`` and can add tasks, rewire
    edges, or change trigger rules. ``orch gen-dag`` never writes or deletes it,
    so structural customization survives regeneration.

    ``tasks`` is keyed by ORCH task name (``dpm3/run_ccd_1``), not the
    Airflow id — deliberately, so renaming a pipeline task surfaces as a
    KeyError at DAG-parse time instead of silently dropping a customization.
    """
    try:
        module = importlib.import_module(f"customize_{dag_id}")
    except ImportError:
        return
    hook = getattr(module, "customize", None)
    if hook is not None:
        hook(dag, tasks)
